const body = $json.body || $json;
const correlationId = body.correlationId || `pivot-${Date.now()}`;
const fixAttempt = Number(body.fix_attempt || body.fixAttempt || 0);
const maxAttempts = 3;
const cost = Number(body.estimated_loop_cost_usd || body.cost || 0);
const maxCost = 15;
const costHalt = cost > maxCost;
const attemptTrigger = fixAttempt >= maxAttempts;
const error = body.error || '';
const toolMethod = body.tool_method || body.toolMethod || '';
const businessGoal = body.business_goal || body.businessGoal || '';
const jobType = costHalt ? 'ops.containment.halted' : 'ops.creative_pivot.proposed';

const text = [
  `CREATIVE PIVOT (HITL)`,
  `cid=${correlationId} attempt=${fixAttempt} cost=${cost}`,
  `goal=${businessGoal}`,
  `tool=${toolMethod}`,
  `error=${error}`,
  costHalt ? `HALT: loop cost > ${maxCost}` : '',
  `Heuristic instructions only. Not auto-deploy. Building mode — no selling.`
].filter(Boolean).join('\n');

return [{
  json: {
    text,
    correlationId,
    costHalt,
    attemptTrigger,
    registerPayload: {
      correlationId,
      jobType,
      goal: businessGoal || 'contain loop',
      source: 'hive-creative-pivot',
      status: 'need_hitl',
      registerTo: 'scorpion',
      summary: text,
      metadata: {
        lane: 'hive-os',
        fixAttempt: String(fixAttempt),
        cost: String(cost),
        telegramRequired: 'false'
      }
    }
  }
}];

const token = $env.TELEGRAM_BOT_TOKEN;
const chatId = $env.HIVE_TELEGRAM_CHAT_ID;
if (!token || !chatId) {
  return [{ json: { ...$json, telegramReady: false } }];
}
return [{ json: { ...$json, telegramReady: true, _telegram: { token, chatId } } }];
